function validate([intervals]) {
  if (!Array.isArray(intervals) || intervals.length < 1 || intervals.length > 50000) return 'intervals needs 1 to 5 * 10^4 entries.';
  for (const item of intervals) {
    if (!Array.isArray(item) || item.length !== 3 || !item.every(Number.isInteger)) return 'Each interval is three integers [l, r, weight].';
    const [l, r, weight] = item;
    if (l < 1 || l > r || r > 1e9) return 'Each interval needs 1 <= l <= r <= 10^9.';
    if (weight < 1 || weight > 1e9) return 'Each weight is between 1 and 10^9.';
  }
  return null;
}

