function maximumWeight(intervals) {
  const n = intervals.length;
  const order = intervals.map((_, index) => index);
  order.sort((a, b) => intervals[a][1] - intervals[b][1]);
  // before[i]: how many sorted intervals end strictly before the i-th sorted one starts.
  const before = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    const start = intervals[order[i]][0];
    let low = 0;
    let high = i;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (intervals[order[mid]][1] < start) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    before[i] = low;
  }
  // Is the sorted index list a lexicographically smaller than b?
  const smaller = (a, b) => {
    for (let p = 0; p < a.length && p < b.length; p++) {
      if (a[p] !== b[p]) return a[p] < b[p];
    }
    return a.length < b.length;
  };
  // score[k][i], picks[k][i]: best total and its smallest index list using at most k of the first i sorted intervals.
  const score = Array.from({ length: 5 }, () => new Array(n + 1).fill(0));
  const picks = Array.from({ length: 5 }, () => Array.from({ length: n + 1 }, () => []));
  for (let k = 1; k <= 4; k++) {
    for (let i = 1; i <= n; i++) {
      const index = order[i - 1];
      const j = before[i - 1];
      const takeScore = score[k - 1][j] + intervals[index][2];
      const takePicks = [...picks[k - 1][j], index].sort((a, b) => a - b);
      score[k][i] = score[k][i - 1];
      picks[k][i] = picks[k][i - 1];
      if (takeScore > score[k][i] || (takeScore === score[k][i] && smaller(takePicks, picks[k][i]))) {
        score[k][i] = takeScore;
        picks[k][i] = takePicks;
      }
    }
  }
  return picks[4][n];
}

