function maximumWeight(intervals) {
  // Try every set of at most 4 pairwise disjoint intervals, listed by increasing index.
  const n = intervals.length;
  const clash = (a, b) => intervals[a][0] <= intervals[b][1] && intervals[b][0] <= intervals[a][1];
  let best = [];
  let bestScore = 0;
  const beats = (list, total) => {
    if (total !== bestScore) return total > bestScore;
    for (let p = 0; p < Math.max(list.length, best.length); p++) {
      if (p >= list.length) return true;
      if (p >= best.length) return false;
      if (list[p] !== best[p]) return list[p] < best[p];
    }
    return false;
  };
  const chosen = [];
  const extend = (from, total) => {
    if (beats(chosen, total)) {
      best = chosen.slice();
      bestScore = total;
    }
    if (chosen.length === 4) return;
    for (let i = from; i < n; i++) {
      if (chosen.some(c => clash(c, i))) continue;
      chosen.push(i);
      extend(i + 1, total + intervals[i][2]);
      chosen.pop();
    }
  };
  extend(0, 0);
  return best;
}

