function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  if (size === 'small') {
    // Few positions and few weights make overlaps, touching ends and tied scores common.
    const n = 1 + pick(9);
    const span = [6, 12, 25][pick(3)];
    const top = [1, 3, 10][pick(3)];
    return [Array.from({ length: n }, () => {
      const l = 1 + pick(span);
      return [l, l + pick(5), 1 + pick(top)];
    })];
  }
  const n = 1500 + pick(501);
  const limit = rand() < 0.5 ? 5000 : 1e9;
  const longest = Math.floor(limit * [0.001, 0.05, 0.4][pick(3)]);
  const top = rand() < 0.5 ? 3 : 1e9;
  return [Array.from({ length: n }, () => {
    const len = pick(longest + 1);
    const l = 1 + pick(limit - len);
    return [l, l + len, 1 + pick(top)];
  })];
}
